referenceSolutions.javascript:
export function backspaceCompare(left        , right        )          {
  function apply(text        )         { const stack           = []; for (const c of text) { if (c === '#') stack.pop(); else stack.push(c); } return stack.join(''); } return apply(left) === apply(right);
}

referenceSolutions.typescript:
export function backspaceCompare(left: string, right: string): boolean {
  function apply(text: string): string { const stack: string[] = []; for (const c of text) { if (c === '#') stack.pop(); else stack.push(c); } return stack.join(''); } return apply(left) === apply(right);
}
